sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_autop;
uniform float amzp_autoSpeed;
uniform float amzp_evolution;
uniform float amzp_dispMode;
uniform float amzp_amount;
uniform float amzp_size;
uniform float2 amzp_offset;
uniform float amzp_pinning;
uniform float amzp_cycleEvo;
uniform float amzp_cycle;
uniform float amzp_seed;
uniform float amzp_overdrawOn;
uniform float amzp_complexity;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float prog(float p) { return (amzp_autop>0.5) ? p + time * (amzp_autoSpeed * 90.0) : p; }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float4 sampleLayer(float2 uv) {
        float2 ins = step(float2(0.0), uv) * step(uv, float2(1.0));
        return amzTexture(0, l2s(clamp(uv, 0.0, 1.0))) * (ins.x * ins.y);
    }
    float hash3d(float3 p) {
        p = fract(p * 0.3183099 + float3(0.1, 0.2, 0.3));
        p *= 17.0;
        return fract(p.x * p.y * p.z * (p.x + p.y + p.z));
    }
    float3 noised(float3 x, float period, float cycleOn, float smoother) {
        float3 p = floor(x);
        float3 w = fract(x);
        float3 u, du;
        if (smoother > 0.5) {
            u = w * w * w * (w * (w * 6.0 - 15.0) + 10.0);
            du = 30.0 * w * w * (w * (w - 2.0) + 1.0);
        } else {
            u = w * w * (3.0 - 2.0 * w);
            du = 6.0 * w * (1.0 - w);
        }
        float z0 = p.z, z1 = p.z + 1.0;
        if (cycleOn > 0.5) { z0 = mod(z0, period); z1 = mod(z1, period); }
        float a = hash3d(float3(p.x, p.y, z0));
        float b = hash3d(float3(p.x + 1.0, p.y, z0));
        float c = hash3d(float3(p.x, p.y + 1.0, z0));
        float d = hash3d(float3(p.x + 1.0, p.y + 1.0, z0));
        float e = hash3d(float3(p.x, p.y, z1));
        float f = hash3d(float3(p.x + 1.0, p.y, z1));
        float g = hash3d(float3(p.x, p.y + 1.0, z1));
        float h = hash3d(float3(p.x + 1.0, p.y + 1.0, z1));
        float k1 = b - a, k2 = c - a, k3 = e - a, k4 = a - b - c + d;
        float k5 = a - c - e + g, k6 = a - b - e + f, k7 = -a + b + c - d + e - f - g + h;
        float v = a + k1 * u.x + k2 * u.y + k3 * u.z + k4 * u.x * u.y + k5 * u.y * u.z + k6 * u.z * u.x + k7 * u.x * u.y * u.z;
        float dx = du.x * (k1 + k4 * u.y + k6 * u.z + k7 * u.y * u.z);
        float dy = du.y * (k2 + k5 * u.z + k4 * u.x + k7 * u.z * u.x);
        return float3(v, dx, dy);
    }
    float2 turbulentWarp(float2 uv) {
        float2 W = layer;
        float aspect = W.x / max(W.y, 1.0);
        float Hp = max(W.y / pxs(), 1.0);
        int mode = int(amzp_dispMode);
        float smoother = (mode == 3 || mode == 4 || mode == 5) ? 1.0 : 0.0;
        float amt = max(amzp_amount, 0.0);
        float cell = max(amzp_size, 1e-3);
        float2 off = float2(amzp_offset.x, -amzp_offset.y) / Hp;
        float2 amzLocal_pos = (float2(uv.x * aspect, uv.y) - off) / cell;
        float z = prog(amzp_evolution) / 360.0;
        float cycleOn = (amzp_cycleEvo>0.5) ? 1.0 : 0.0;
        float period = max(floor(amzp_cycle + 0.5), 1.0);
        float3 sd = floor(amzp_seed + 0.5) * float3(13.0, 71.0, 0.0);
        float2 disp = float2(0.0);
        float norm = 0.0, amp = 1.0;
        float gain = smoother > 0.5 ? 0.4 : 0.5;
        float2 p = amzLocal_pos;
        float zScale = 1.0;
        for (int i = 0; i < 6; i++) {
            float wgt = clamp(amzp_complexity - float(i), 0.0, 1.0) * amp;
            if (wgt > 0.0) {
                float3 q = float3(p, z * zScale) + sd;
                float3 n = noised(q, period, cycleOn, smoother);
                float2 d;
                if (mode == 1 || mode == 4) d = n.yz * 0.5;
                else if (mode == 2 || mode == 5) d = float2(-n.z, n.y) * 0.5;
                else if (mode == 6) d = float2(0.0, (n.x - 0.5) * 2.0);
                else if (mode == 7) d = float2((n.x - 0.5) * 2.0, 0.0);
                else if (mode == 8) {
                    float cx = noised(float3(sd.x, q.y, q.z), period, cycleOn, smoother).x;
                    float cy = noised(float3(q.x, sd.y + 41.0, q.z), period, cycleOn, smoother).x;
                    d = float2(cx - 0.5, cy - 0.5) * 2.0;
                } else {
                    float v2 = noised(q + float3(31.7, 17.3, 0.0), period, cycleOn, smoother).x;
                    d = float2(n.x - 0.5, v2 - 0.5) * 2.0;
                }
                disp += d * wgt;
                norm += wgt;
            }
            amp *= gain;
            p = float2(p.x * 1.6 - p.y * 1.2, p.x * 1.2 + p.y * 1.6);
            zScale *= 2.0;
            period *= 2.0;
        }
        float2 d = disp / max(norm, 1e-4);
        float len = length(d);
        if (len > 1.0) d /= len;
        d *= amt;
        float m = max(2.0 * amt, 1e-3);
        float wx = smoothstep(0.0, m, min(uv.x * aspect, (1.0 - uv.x) * aspect));
        float wy = smoothstep(0.0, m, min(uv.y, 1.0 - uv.y));
        if (int(amzp_pinning) == 1) { d.x *= wx; d.y *= wy; }
        else if (int(amzp_pinning) == 2) { d.y *= wy; }
        else if (int(amzp_pinning) == 3) { d.x *= wx; }
        else if (int(amzp_pinning) == 4) { d *= min(wx, wy); }
        else if (int(amzp_pinning) == 5) { d *= wy; }
        else if (int(amzp_pinning) == 6) { d *= wx; }
        d.x /= aspect;
        return uv + d;
    }
    void nmMain() {
        amzOutput = sampleLayer(turbulentWarp(amzLayerNorm()));
    }
    void amzRender() {
        nmMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
